  ('pep-grade3-first-term-2024-revision-q30', 'pep-grade3-first-term-2024', 0, 'Being a good guest', 'final_review', 30, 'speaking', '综合口语：完成一段 5 句左右的小对话，至少包含一次问候、一次家庭或动物介绍、一次颜色或数字表达。', NULL, '"参考：Hi! My name is Amy. Nice to meet you. This is my brother. He has a cute cat. It is black and he is six years old."'::jsonb, '参考：Hi! My name is Amy. Nice to meet you. This is my brother. He has a cute cat. It is black and he is six years old.', NULL, 3, ARRAY['pep-appendix', 'final_review', 'revision']::text[], NOW())
